/bin/bash -lc "python3 - <<'PY'
import ast,copy,hashlib,json,subprocess
from pathlib import Path
root=Path('/workspace')
def resolve(ref):
    return json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve',ref],text=True))
runtime=resolve('run://r-001'); workspace=resolve('workspace://w-001')
p=json.loads((root/'proposal.json').read_text())
def validate(value,schema,path='study'):
    typ=schema.get('type')
    ok={'object':lambda v:isinstance(v,dict),'array':lambda v:isinstance(v,list),'string':lambda v:isinstance(v,str),'boolean':lambda v:isinstance(v,bool)}
    if typ: assert ok[typ](value),(path,'type',typ)
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if isinstance(value,dict):
        assert all(k in value for k in schema.get('required',[])),(path,'required')
        if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra')
        for k,v in value.items():
            if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),(path,'minItems')
        if 'items' in schema:
            for i,v in enumerate(value):validate(v,schema['items'],path+f'[{i}]')
    if isinstance(value,str):assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],runtime['study_schema'])
